// === Tab: mySketch ===
let colors = ["#c0bd9b", "#a08b8d", "#c69322", "#005e84", "#42a5e4", "#4ad3c8", "#02c287"]

let particles = []
let frameWidth, simplex
let fc1 = 0
let fc2 = 0

function setup() {
	createCanvas(windowWidth, windowHeight);
	let bgIndex = floor(random(4))
	background(colors[bgIndex])

	simplex = new openSimplexNoise(Date.now())
	let m = max(windowWidth, windowHeight)
	frameWidth = m * 0.02
	while (fc1 == fc2) {
		fc1 = random(colors);
		fc2 = random(colors);
	}
}

function draw() {
	blendMode(OVERLAY)
	if (frameCount < 2500) {

		particles.push(new particle(random(width * 0.44, width * 0.55), height))
		for (let p of particles) {
			p.move()
			p.show()
			p.end()
		}
		push()
		blendMode(BLEND)
		noFill()
		let stroker = map(frameCount, 0, 2500, 0, 1)
		let s = color(spectral.mix(fc1, fc2, stroker))
		stroke(s)
		strokeWeight(0.01)
		rectMode(CENTER)
		let framing = map(frameCount, 0, 2500, 0, frameWidth)


		beginShape()
		for (let x = framing / 2; x <= width - framing / 2; x += 5) {
			let yoff = simplex.noise2D(x / 10, frameCount / 5) * framing
			vertex(x, framing / 2 + yoff)
		}
		for (let y = framing / 2; y <= width - framing / 2; y += 5) {
			let xoff = simplex.noise2D(y / 10, frameCount / 5) * framing
			vertex(width - framing / 2 + xoff, y)
		}

		for (let x = width - framing / 2; x >= framing / 2; x -= 5) {
			var yoff = simplex.noise2D(1 + x / 10, frameCount / 5) * framing
			vertex(x, height - framing / 2 + yoff)
		}

		for (let y = width - framing / 2; y >= framing / 2; y -= 5) {
			var xoff = simplex.noise2D(1 + y / 10, frameCount / 5) * framing
			vertex(framing / 2 + xoff, y)
		}


		endShape(CLOSE)


		pop()
	}
}

class particle {
	constructor(x, y) {
		this.pos = createVector(x, y)
		this.vel = createVector(random(-0.1, 0.1), -2)
		let ny = map(noise(x / 50, frameCount / 50), 0, 1, 0, 0.01)
		this.acc = createVector(random(-0.01, 0.01), ny)
		this.color = colorMixer(this.pos.x, colors)
	}

	move() {

		this.vel.add(this.acc);
		this.vel.rotate(sin(frameCount / 100) * 0.1)
		this.pos.add(this.vel);

	}

	show() {
		noStroke()
		fill(this.color)
		ellipse(this.pos.x, this.pos.y, 1)
		ellipse(this.pos.x, height - this.pos.y, 1)

	}

	end() {
		if (this.y > height + 10) {
			let index = indexOf(this)
			particles.splice(index, 1)
		}
	}
}

function colorMixer(x, colorArray) {

	let c = map(noise(x / 50, frameCount / 100), 0, 1, 0, colorArray.length)
	let c1 = floor(c) % colorArray.length
	let c2 = floor(c + 1) % colorArray.length

	let color1 = colorArray[c1]
	let color2 = colorArray[c2]
	let mix = fract(c)
	let coloring = color(spectral.mix(color1, color2, mix))

	return coloring
}

